def _walls(study, calibrate, source):
    from scipy.optimize import least_squares
    nominal = np.ones(8)
    pulses = study.get('reference_tracer_pulses')
    if not pulses:
        return nominal
    modes = np.array([np.tensordot(p['w_pulse'], source, axes=1) for p in pulses])
    observed = np.column_stack([calibrate(p['y_pulse_raw']) for p in pulses])
    scale = max(np.sqrt(np.mean(observed ** 2)), 0.01)
    if np.sqrt(np.mean((_response(study, nominal, modes)[0] - observed) ** 2)) < 0.0002 * scale:
        return nominal
    groups = (([0, 1], [4, 5]), ([0], [1], [4], [5]), tuple(([i] for i in range(8))))
    best = (np.inf, nominal)
    for group in groups:

        def expand(x):
            result = nominal.copy()
            for (z, inds) in zip(x, group):
                result[inds] = z
            return result

        def fit(columns):

            def residual(x):
                return ((_response(study, expand(x), modes)[0] - observed)[:, columns] / scale).ravel()
            return expand(least_squares(residual, np.ones(len(group)), bounds=(0.0, np.inf), max_nfev=60, gtol=1e-10).x)
        wall = fit(slice(None))
        if len(pulses) > 1:
            score = max((np.sqrt(np.mean((_response(study, fit(np.arange(len(pulses)) != i), modes)[0][:, i] - observed[:, i]) ** 2)) for i in range(len(pulses))))
        else:
            score = np.sqrt(np.mean((_response(study, wall, modes)[0] - observed) ** 2))
        if score < best[0]:
            best = (score, wall)
        if score < 0.0002 * scale:
            return wall
    baseline = np.max(np.sqrt(np.mean((_response(study, nominal, modes)[0] - observed) ** 2, axis=0)))
    return best[1] if best[0] < baseline else nominal

def _project(q, cap, total):
    if total <= 0:
        return np.zeros_like(q)
    if total >= len(q) * cap:
        return np.full_like(q, cap)
    (lo, hi) = (np.min(q) - cap, np.max(q))
    for _ in range(53):
        mid = (lo + hi) * 0.5
        if np.clip(q - mid, 0.0, cap).sum() > total:
            lo = mid
        else:
            hi = mid
    return np.clip(q - (lo + hi) * 0.5, 0.0, cap)

def _dual(g, w, cap):
    free = (w > 1e-10) & (w < cap - 1e-10)
    if free.any():
        return float(np.mean(g[free]))
    upper = w > cap / 2
    if upper.all():
        return float(g.max())
    if not upper.any():
        return float(g.min())
    return float(0.5 * (g[upper].max() + g[~upper].min()))
